import{_ as n,C as e,c as r,o as s,aj as l,G as i,w as h}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"FACT Most Traders Will Fail to Achieve Consistent Profitability","description":"","frontmatter":{"outline":"deep","prev":{"text":"Additional Documentation","link":"/trading-with-pav/additional-documentation"},"next":{"text":"The Journey","link":"/trading-with-pav/the-journey"}},"headers":[],"relativePath":"trading-with-pav/fact-most-traders-will-fail-to-achieve-consistent-profitability.md","filePath":"trading-with-pav/fact-most-traders-will-fail-to-achieve-consistent-profitability.md"}'),c={name:"trading-with-pav/fact-most-traders-will-fail-to-achieve-consistent-profitability.md"};function d(f,t,m,p,u,y){const a=e("GraphComment"),o=e("ClientOnly");return s(),r("div",null,[t[0]||(t[0]=l('<h1 id="fact-most-traders-will-fail-to-achieve-consistent-profitability" tabindex="-1">FACT Most Traders Will Fail to Achieve Consistent Profitability <a class="header-anchor" href="#fact-most-traders-will-fail-to-achieve-consistent-profitability" aria-label="Permalink to &quot;FACT Most Traders Will Fail to Achieve Consistent Profitability&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#fact-most-traders-will-fail-to-achieve-consistent-profitability-1">FACT: Most Traders Will Fail to Achieve Consistent Profitability</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h3 id="fact-most-traders-will-fail-to-achieve-consistent-profitability-1" tabindex="-1">FACT: Most Traders Will Fail to Achieve Consistent Profitability <a class="header-anchor" href="#fact-most-traders-will-fail-to-achieve-consistent-profitability-1" aria-label="Permalink to &quot;FACT: Most Traders Will Fail to Achieve Consistent Profitability&quot;">​</a></h3><p>In previous articles I’ve presented my theory of the markets, my method of analysis and my trading strategy. Yet, I still expect most readers will fail to achieve consistent profitability.<br> Why is that?</p><p>Let’s consider the failure rate within this industry. While I have no authoritative source to provide, the failure rate is often quoted as being anywhere from 80-95%. I’d suggest it’s possibly even worse than 95%.</p><p>While I hope to achieve much better than this, through the detailed explanations and examples<br> I’ve provided in the course (and through these articles for lifetime if you forget what you learned or got out of touch and ongoing education posts of my trades), I’d be naïve to think that all members of my course will succeed.</p><p>The reality is that most won’t.</p><h4 id="consistent-loser-to-winner" tabindex="-1">Consistent loser to winner <a class="header-anchor" href="#consistent-loser-to-winner" aria-label="Permalink to &quot;Consistent loser to winner&quot;">​</a></h4><p>The strategy we’ve provided is simple in concept – fade weakness when price interacts with S/R, and fade weakness in a pullback within a trend and volume analysis plus volume profile S/R Zones.</p><p>The reality though is that it’s hard to trade in the uncertainty of market price action. It’s the infinite variations of the patterns that will have you doubting and second guessing your analysis.</p><p>Every situation in the markets is unique. That’s what makes it so hard to trade.</p><p>Your results will vary anywhere on the scale from consistent loser to consistent winner, dependent on:</p><ul><li>Your ability to perceive the shifting forces of strength and weakness within the market, and place that within the context of higher timeframe structure, in order to identify the likely future direction of price action;</li><li>Your ability to identify areas of trade opportunity within that price action, and to time entry and exit decisions in order to minimize risk and maximize profit potential; and</li><li>Your ability to trust yourself and your strategy, with sufficient confidence to allow you to take the entry and exit signals without hesitation.</li></ul><h4 id="why-will-most-fail" tabindex="-1">Why will most fail ? <a class="header-anchor" href="#why-will-most-fail" aria-label="Permalink to &quot;Why will most fail ?&quot;">​</a></h4><p>All three of the above are a result of experience. They don’t come from doing this course or reading this article. They don’t come from watching a video of me trade. They come as a result of getting in the market and trading; making mistakes, identifying them, learning from them, and improving.</p><p>Learning to operate in the uncertain market environment, is a process (or journey) of gradual improvement.</p><p>So, why will most fail? Simply, because they won’t last the journey! They’ll quit before they make it.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',18)),i(o,null,{default:h(()=>[i(a)]),_:1})])}const b=n(c,[["render",d]]);export{v as __pageData,b as default};
